<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=post_int('customer_id');$rid=post_int('room_id');$in=post('checkin_date');if(post('action')==='cancel'){$pdo->prepare('UPDATE reservation SET status=0 WHERE customer_id=? AND room_id=? AND checkin_date=?')->execute([$cid,$rid,$in]);$pdo->prepare('DELETE FROM room_sales WHERE customer_id=? AND room_id=? AND checkin_date=?')->execute([$cid,$rid,$in]);flash('success','Reservation cancelled.');}redirect('reservations.php');}
$rows=$pdo->query("SELECT r.*,CONCAT(c.customer_firstname,' ',c.customer_lastname) customer,rm.room_type FROM reservation r JOIN customer c ON c.customer_id=r.customer_id JOIN room rm ON rm.room_id=r.room_id ORDER BY r.checkin_date DESC")->fetchAll();page_header('Reservations','reservation');?>
<div class="page-head"><h1>Reservations</h1><a class="btn primary" href="reservation.php">New Reservation</a></div><section class="card table-wrap"><table><thead><tr><th>Customer</th><th>Room</th><th>Check-in</th><th>Check-out</th><th>Reservation Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?></td><td>#<?=$r['room_id']?> · <?=e($r['room_type'])?></td><td><?=$r['checkin_date']?></td><td><?=$r['checkout_date']?></td><td><?=$r['reservation_date']?></td><td><span class="badge <?=$r['status']?'ok':'off'?>"><?=$r['status']?'Active':'Cancelled'?></span></td><td><?php if($r['status']):?><form method="post" onsubmit="return confirm('Cancel reservation?')"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="customer_id" value="<?=$r['customer_id']?>"><input type="hidden" name="room_id" value="<?=$r['room_id']?>"><input type="hidden" name="checkin_date" value="<?=e($r['checkin_date'])?>"><button class="danger-link">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>
